use std::path::Path;

/// `THIRD_PARTY_NOTICES.txt` is generated by `pnpm check:licenses` (scripts/gen-licenses.mjs) and
/// shipped inside the installer. A plain `cargo build` or `cargo clippy` on a fresh clone has not
/// run that script yet, so leave a clearly marked stand-in; the release workflow refuses to
/// publish an installer that still contains it.
const STAND_IN: &str =
    "STAND-IN: run `pnpm check:licenses` to generate the real third-party notices.\n";

fn main() {
    let notices = Path::new("resources/THIRD_PARTY_NOTICES.txt");
    if !notices.exists() {
        std::fs::write(notices, STAND_IN).expect("write the notices stand-in");
    }
    tauri_build::build()
}
